/* eslint-disable max-lines */
import { Component, h, Element, Event, Host, Prop, Watch, State, EventEmitter, VNode } from '@stencil/core';
import { convertDataToEntities, DataEntity, processCheck } from '@src/components/ks-tree-view/utils';
import {
  toPathKey,
  toPathKeys,
  toRawValues,
  formatStrategyValues,
  toPathOptions,
  getValueByKeyPath,
  getKey,
  getDefaultLabel,
  defaultFilter,
  noop,
} from './utils';
import { Value } from '@src/components/ks-menu-item/types';
import {
  ShowCheckedStrategy,
  SingleValueType,
  CascaderDataNode,
  CascaderSearchNode,
  SearchConfig,
  CascaderPartProps,
  CascaderMultiple,
  getMergedMultiple,
  getMultipleConfig,
} from './types';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { DetailArgs } from '@src/shared/dom';
import { t } from '@src/shared/i18n';
import { searchMessages, selectMessages } from '@fe-infra/keystone-locales';
import { getPartProps, Status } from '@src/shared/base-props';
import { SEARCH_MARK, VALUE_SPLIT } from './constants';
import { Slot, Slots, Uncontrollable, Vue2ValueFix } from '@src/framework/decorators';
import { Provide } from '@src/framework/runtime-context';
import { CascaderContext, CascaderContextValue } from './context';
import { ValueField } from '../ks-value-field/types';
import { KsTooltip } from '../ks-tooltip';
import { FormContextValueReconcile } from '../ks-form/FormContextValueReconcile';
import { JSX } from '@src/components';
import { asObject } from '@src/shared/type-utils';
import { KsIconChevronUp, KsIconSearch } from '@fe-infra/keystone-icons-stencil';

const prefix = 'cascader';

/**
 * @slot empty - Empty slot for empty states.
 * @slot prefix - Allows customization of the content displayed before the input area.
 * @slot suffix - Allows customization of the content displayed after the input area, typically for icons.
 * @slot field - Replaces the entire value field content.
 * @slot popupFooter - Slot for custom footer for the dropdown menu.
 * @part tooltip
 * @part popup - The popup container.
 * @part columns
 */
@Component({
  tag: 'ks-cascader',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsCascader extends FormBaseComponent<SingleValueType | SingleValueType[]> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsCascaderElement;

  // ====== Value Field Props ======
  /** Whether the cascader input field is clearable. */
  @Prop() clearable = false;

  /** Whether the cascader input field should automatically receive focus on mount. */
  @Prop() autoFocus = false;

  /** Whether the cascader input field should collapse when no options are available. */
  @Prop() tagsEllipsis = false;

  /** Placeholder text for the cascader input field. */
  @Prop() placeholder = t(selectMessages.placeholder);

  /** Status of the cascader input field. */
  @Prop() @FormContextValueReconcile() status?: Status;

  /** Function to map cascader data nodes to value fields. */
  @Prop() mapItemsToValueFields: (items: CascaderDataNode[][]) => ValueField[] = (items) =>
    items.map((path) => ({
      value: path.map((item) => item.value).join(VALUE_SPLIT),
      label: path.map((item) => item.label?.toString()).join(' / '),
    }));

  // ====== Cascader Panel Props ======
  /** Cascader options. */
  @Prop() options: CascaderDataNode[] = [];

  /** Whether the cascader is disabled. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;

  /** Whether the cascader allows multiple selections, or multiple-mode configuration. */
  @Prop() multiple: CascaderMultiple = false;

  private get mergedMultiple() {
    return getMergedMultiple(this.multiple);
  }

  private get multipleConfig() {
    return getMultipleConfig(this.multiple);
  }

  /** Strategy for displaying checked items in the cascader panel. */
  @Prop() showCheckedStrategy: ShowCheckedStrategy = 'parent';

  /** Whether to use the full path of the selected item as value. */
  @Prop() valueFormatStrategy: 'fullPath' | 'single' = 'fullPath';

  /** Selected value(s) for the cascader. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: SingleValueType | SingleValueType[] | Value | Value[];
  @Watch('value')
  updateInternalValueState() {
    let mergedValue = this.value || this.defaultValue || [];
    if (this.valueFormatStrategy === 'single') {
      // Convert value to path key
      if (this.mergedMultiple) {
        mergedValue = (mergedValue as Value[]).map(
          (value: Value) => this.keyEntities[value]?.nodes.map((node) => node.value) || [],
        );
      } else {
        mergedValue = this.keyEntities[mergedValue as Value]?.nodes.map((node) => node.value) || [];
      }
    }
    this.internalValueState = mergedValue as SingleValueType | SingleValueType[];
  }

  /** Default selected value(s) for the cascader. */
  @Prop() defaultValue?: SingleValueType | SingleValueType[] | Value | Value[];

  /** Whether to trigger change on select. */
  @Prop() changeOnSelect?: boolean;

  /** Function to load cascader options asynchronously. */
  @Prop() loadData?: (selectOptions: CascaderDataNode[]) => Promise<void> | void;

  /** Pre-loaded keys for cascader options. */
  @Prop() loadedKeys?: Value[][];

  /** Whether to enable search functionality in the cascader panel. */
  @Prop() search?: SearchConfig | boolean;

  /** Search value for the cascader panel. */
  @Prop() searchValue?: string;
  @Watch('searchValue')
  updateInternalSearchValueState(newValue?: string) {
    this.internalSearchValue = newValue || '';
  }

  // ====== tooltip props ======
  /** Whether the cascader panel is open. */
  @Prop() open?: boolean;

  /** Default open state for the cascader panel. */
  @Prop() defaultOpen?: boolean;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() internalOpenState?: boolean;

  /** Height of the cascader panel popup. */
  @Prop() popupHeight: KsTooltip['popupHeight'] = { max: 381 };

  /** Width of the cascader panel popup. */
  @Prop() popupWidth?: KsTooltip['popupWidth'];

  /** Custom props for cascader parts. */
  @Prop() partProps?: CascaderPartProps;

  /** Whether to enable virtual scrolling for the cascader panel. Virtual scrolling is enabled by default; set this prop to `false` to disable it. */
  @Prop() virtual?:
    | boolean
    | { estimatedItemHeight: number | ((item: CascaderDataNode | CascaderSearchNode) => number) };

  @State() internalValueState?: SingleValueType | SingleValueType[] = [];

  /** Event fired when the cascader value changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<
    DetailArgs<[SingleValueType | SingleValueType[] | Value | Value[], CascaderDataNode[] | CascaderDataNode[][]]>
  >;

  /** Event fired when the cascader search value changes. */
  @Event({ bubbles: false, composed: false }) ksSearch!: EventEmitter<string>;

  /** Event fired when the cascader panel open state changes. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;

  /** Event fired when the cascader options are loaded. */
  @Event({ bubbles: false, composed: false }) ksLoad!: EventEmitter<Value[][]>;

  /** Custom slot for empty states */
  @Slot({ slotname: 'empty' }) private emptySlot?: Slots;

  /** Custom footer for the dropdown menu. */
  @Slot({ slotname: 'popupFooter' })
  private popupFooterSlot?: Slots;

  /** The component that display in the suffix area */
  @Slot({ slotname: 'suffix' }) private suffixSlot?: Slots;

  /** The component that display in the prefix area */
  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  // ====== Entities ======
  private keyEntities: Record<Value, DataEntity<CascaderDataNode>> = {};
  private pathKeyEntities: Record<string, DataEntity<CascaderDataNode>> = {};
  @Watch('options')
  transformOptionsToEntities() {
    interface Entities {
      keyEntities: Record<Value, DataEntity<CascaderDataNode>>;
      posEntities: Record<string, DataEntity<CascaderDataNode>>;
      pathKeyEntities: Record<string, DataEntity<CascaderDataNode>>;
    }
    const entities = convertDataToEntities<Entities>(this.options, {
      initEntities: (entities) => ({
        ...entities,
        pathKeyEntities: {},
      }),
      processEntity: (entity, entities) => {
        const pathKey = entity.nodes.map((node) => node.value).join(VALUE_SPLIT);

        (entities as unknown as Entities).pathKeyEntities[pathKey] = entity;

        // Override the original key
        // This is for format keys
        entity.key = pathKey;
      },
    });
    this.keyEntities = entities.keyEntities;
    this.pathKeyEntities = entities.pathKeyEntities;

    // call the value watcher to update the internal value state
    this.updateInternalValueState();
  }

  // ====== Value State ======
  @Watch('internalValueState')
  handleValueStateChange() {
    const rawValues = toRawValues(this.internalValueState);
    if (!this.mergedMultiple || !rawValues.length) {
      this.checkedState = {
        checkedKeys: rawValues,
        halfCheckedKeys: [],
        key2CheckedChildrenCount: new Map(),
      };
      return;
    } else {
      const pathKeyValues = toPathKeys(rawValues);
      const { checkedKeys, halfCheckedKeys, key2CheckedChildrenCount } = processCheck(
        pathKeyValues,
        true,
        this.pathKeyEntities,
        { getKey },
      );
      this.checkedState = {
        checkedKeys: getValueByKeyPath(checkedKeys, this.pathKeyEntities),
        halfCheckedKeys: getValueByKeyPath(halfCheckedKeys, this.pathKeyEntities),
        key2CheckedChildrenCount,
      };
    }
  }
  /**
   * this is a state to store checked keys and half checked keys
   *
   * - checkedKeys: keys that are checked
   * - halfCheckedKeys: keys that are half checked
   *
   * We do not need to decorate it with `@State()` because it is updated in
   * watcher function for internalValueState. So we can ensure that it is
   * **always** up-to-date.
   */
  private checkedState: {
    checkedKeys: SingleValueType[];
    halfCheckedKeys: SingleValueType[];
    key2CheckedChildrenCount: Map<Value, number>;
  } = {
    checkedKeys: [],
    halfCheckedKeys: [],
    key2CheckedChildrenCount: new Map(),
  };

  // ====== Event ======
  private onSelect = (valuePath: SingleValueType, originalChecked: boolean) => {
    if (!this.mergedMultiple) {
      this.triggerChange(valuePath);
    } else {
      const pathKey = toPathKey(valuePath);
      const checkedPathKeys = toPathKeys(this.checkedState.checkedKeys);
      const halfCheckedPathKeys = toPathKeys(this.checkedState.halfCheckedKeys);

      const isChecked = originalChecked;

      // ====== do update ======
      const nextRawCheckedKeys = isChecked
        ? checkedPathKeys.filter((key) => key !== pathKey)
        : [...checkedPathKeys, pathKey];

      // ====== process check ======
      let checkedKeys: Value[];
      if (isChecked) {
        ({ checkedKeys } = processCheck(
          nextRawCheckedKeys,
          { checked: false, halfCheckedKeys: halfCheckedPathKeys },
          this.pathKeyEntities,
          { getKey },
        ));
      } else {
        ({ checkedKeys } = processCheck(nextRawCheckedKeys, true, this.pathKeyEntities, { getKey }));
      }

      const formattedKeys = formatStrategyValues(checkedKeys, this.pathKeyEntities, this.showCheckedStrategy);
      const nextCheckedValues = getValueByKeyPath(formattedKeys, this.pathKeyEntities);
      this.triggerChange(nextCheckedValues);
    }
  };

  private onSelectAll = (valuePaths: SingleValueType[], checked: boolean) => {
    if (!this.mergedMultiple || !valuePaths.length) {
      return;
    }

    const targetPathKeys = toPathKeys(valuePaths);
    const checkedPathKeys = toPathKeys(this.checkedState.checkedKeys);
    const halfCheckedPathKeys = toPathKeys(this.checkedState.halfCheckedKeys);
    const nextRawCheckedKeys = checked
      ? [...checkedPathKeys, ...targetPathKeys.filter((key) => !checkedPathKeys.includes(key))]
      : checkedPathKeys.filter((key) => !targetPathKeys.includes(key));

    let checkedKeys: Value[];
    if (checked) {
      ({ checkedKeys } = processCheck(nextRawCheckedKeys, true, this.pathKeyEntities, { getKey }));
    } else {
      ({ checkedKeys } = processCheck(
        nextRawCheckedKeys,
        { checked: false, halfCheckedKeys: halfCheckedPathKeys },
        this.pathKeyEntities,
        { getKey },
      ));
    }

    const formattedKeys = formatStrategyValues(checkedKeys, this.pathKeyEntities, this.showCheckedStrategy);
    const nextCheckedValues = getValueByKeyPath(formattedKeys, this.pathKeyEntities);
    this.triggerChange(nextCheckedValues);
  };

  private triggerChange = (nextValues: SingleValueType | SingleValueType[]) => {
    if (this.value === undefined) {
      // uncontrolled
      this.internalValueState = nextValues;
    }
    // trigger change
    const nextRawValues = toRawValues(nextValues);
    const valueOptions = nextRawValues.map((val) => toPathOptions(val, this.options).map(({ option }) => option));

    let nextValuesForTrigger: SingleValueType[] | Value[] = nextRawValues;
    if (this.valueFormatStrategy === 'single') {
      // if valueFormatStrategy is single, we need to extract the last value in the path
      nextValuesForTrigger = nextRawValues.map((val) => val[val.length - 1]!);
    }
    const triggerValues = this.mergedMultiple ? nextValuesForTrigger : nextValuesForTrigger[0]!;
    const triggerOptions = this.mergedMultiple ? valueOptions : valueOptions[0]!;

    this.ksChange.emit(DetailArgs(triggerValues, triggerOptions));
  };

  // ====== Search ======
  @State() internalSearchValue = '';
  private searchOptions: CascaderSearchNode[] = [];
  @Watch('internalSearchValue')
  handleSearchValueChange() {
    if (!this.internalSearchValue && !this.search) {
      if (this.searchOptions.length) {
        this.searchOptions = [];
      }
      return;
    }

    const enableHalfPath = this.mergedMultiple || this.changeOnSelect;

    const { filter = defaultFilter, render = null, sort = null, limit = 50 } = asObject(this.search) || {};
    const filteredOptions: CascaderSearchNode[] = [];

    const dig = (list: CascaderDataNode[], pathOptions: CascaderDataNode[], parentDisabled = false) => {
      list.forEach((option) => {
        // Perf saving when `sort` is disabled and `limit` is provided
        if (!sort && limit !== false && limit > 0 && filteredOptions.length >= limit) {
          return;
        }

        const connectedPathOptions = [...pathOptions, option];
        const { children } = option;

        const mergedDisabled = parentDisabled || option.disabled;

        // If current option is filterable
        if (
          // If is leaf option
          !children ||
          children.length === 0 ||
          // If is changeOnSelect or multiple
          enableHalfPath
        ) {
          if (filter!(this.internalSearchValue, connectedPathOptions)) {
            const defaultStr = getDefaultLabel(this.internalSearchValue, connectedPathOptions);
            const idx = defaultStr.toLocaleLowerCase().indexOf(this.internalSearchValue.toLowerCase());
            filteredOptions.push({
              ...option,
              disabled: mergedDisabled,
              label: render ? () => render(this.internalSearchValue, connectedPathOptions) : defaultStr,
              highlight: idx === -1 ? null : [idx, idx + this.internalSearchValue.length],
              [SEARCH_MARK]: connectedPathOptions,
              children: undefined,
            });
          }
        }

        if (children) {
          dig(option.children!, connectedPathOptions, mergedDisabled);
        }
      });
    };

    dig(this.options, []);

    // Sort
    if (sort) {
      filteredOptions.sort((a, b) => sort(a, b, this.internalSearchValue));
    }

    this.searchOptions = limit !== false && limit > 0 ? filteredOptions.slice(0, limit) : filteredOptions;
  }

  private internalOnSearch = ({ detail: searchText }: CustomEvent<string>) => {
    if (this.searchValue === undefined) {
      // uncontrolled
      this.internalSearchValue = searchText;
    }
    // trigger event
    this.ksSearch.emit(searchText);
  };

  get displayValue() {
    if (this.mergedMultiple) {
      const values = (this.internalValueState || []) as SingleValueType[];
      const items = values.map((item) => {
        const pathOptions = toPathOptions(item, this.options);
        return pathOptions.map(({ option }) => option);
      });
      return this.mapItemsToValueFields(items);
    } else {
      const value = this.internalValueState as SingleValueType;
      const pathOptions = toPathOptions(value, this.options);
      return pathOptions.length ? this.mapItemsToValueFields([pathOptions.map(({ option }) => option)]) : [];
    }
  }

  private onTooltipOpenChange = ({ detail: open }: { detail: boolean }) => {
    !this.disabled && (this.internalOpenState = open);
  };
  private onCascaderPanelListToggleOpen = (open?: boolean) => {
    this.internalOpenState = open;
  };
  private onValueFieldChange: JSX.KsValueField['onKsChange'] = ({ detail }) => {
    const pathKeys = detail.map((item) => item.value);
    const entities = pathKeys.map((pathKeys) => this.pathKeyEntities[pathKeys]);
    const nextValues = entities.map((entity) => entity!.nodes.map((node) => node.value));
    if (this.mergedMultiple) {
      this.triggerChange(nextValues);
    } else {
      this.triggerChange(nextValues[0]!);
    }
  };

  private setPanelListProps = (list?: HTMLKsCascaderPanelListElement) => {
    if (!list) {
      return;
    }

    list.multiple = this.mergedMultiple;
    list.columnSelectAll = this.multipleConfig.columnSelectAll;
  };

  render() {
    const placeholder = asObject(this.search)?.placeholder || t(searchMessages.placeholder);
    return (
      <Host class="KsCascader">
        <ks-popover
          part="tooltip"
          class={`${prefix}__tooltip`}
          size="auto"
          trigger="click"
          placement="bottom-start"
          disabled={this.disabled}
          open={this.internalOpenState}
          arrow={false}
          onKsOpenChange={this.onTooltipOpenChange}
          popupHeight={this.popupHeight}
          popupWidth={this.popupWidth}
          {...getPartProps(this, 'tooltip')}
        >
          <div slot="content" part="popup" class={`${prefix}__popup`} {...getPartProps(this, 'popup')}>
            {this.search && (
              <div class={`${prefix}__search`}>
                <ks-input placeholder={placeholder} value={this.internalSearchValue} onKsChange={this.internalOnSearch}>
                  <KsIconSearch size="14" slot="prefix" />
                </ks-input>
              </div>
            )}
            <ks-cascader-panel-list
              ref={this.setPanelListProps}
              part="columns"
              searchValue={this.internalSearchValue}
              multiple={this.mergedMultiple}
              columnSelectAll={this.multipleConfig.columnSelectAll}
              toggleOpen={this.onCascaderPanelListToggleOpen}
              open={this.internalOpenState}
              disabled={this.disabled}
              options={this.options}
              values={this.checkedState.checkedKeys}
              halfValues={this.checkedState.halfCheckedKeys}
              key2CheckedChildrenCount={this.checkedState.key2CheckedChildrenCount}
              changeOnSelect={this.changeOnSelect}
              onSelect={this.onSelect}
              onSelectAll={this.onSelectAll}
              loadData={this.loadData}
              loadedKeys={this.loadedKeys}
              onLoadData={this.ksLoad.emit}
              searchOptions={this.searchOptions}
              columnProps={getPartProps(this, 'columns')}
              virtual={this.virtual}
            >
              {this.emptySlot && <slot name="empty" slot="empty" />}
              {this.passThroughSlots}
            </ks-cascader-panel-list>
            {this.popupFooterSlot && (
              <div class={`${prefix}__footer`}>
                <slot name="popupFooter" />
              </div>
            )}
          </div>
          <slot name="field">
            <ks-value-field
              class={prefix}
              type={this.mergedMultiple ? 'tagged' : 'texted'}
              tagsEllipsis={this.tagsEllipsis}
              value={this.displayValue}
              focusElement={this.internalOpenState}
              disabled={this.disabled}
              status={this.status}
              placeholder={this.placeholder}
              enableInput={false}
              onKsChange={this.onValueFieldChange}
              clearable={this.clearable}
            >
              {this.prefixSlot && <slot slot="prefix" name="prefix" />}
              <div slot="suffix" class={`${prefix}__suffix`}>
                {this.suffixSlot && <slot name="suffix" />}
                <KsIconChevronUp
                  size="14"
                  class={{
                    icon: true,
                    [`icon--down`]: !this.internalOpenState,
                  }}
                />
              </div>
            </ks-value-field>
          </slot>
        </ks-popover>
      </Host>
    );
  }

  componentWillLoad() {
    this.transformOptionsToEntities();
  }

  // ====== Context ======
  @Provide({
    context: CascaderContext,
  })
  protected context: CascaderContextValue = {
    wrapWithSlot: (slotName: string, children: unknown) => this.wrapWithSlot?.(slotName, children),
    dynamicChildren: [],
    setDynamicRenderDeps: (children: unknown[], index: number | 'search') => {
      if (index === 'search') {
        this.context.dynamicChildren = [children];
      } else {
        this.context.dynamicChildren[index] = children;
      }
      this.setDynamicRenderDeps?.(this.context.dynamicChildren.flat());
    },
    getPassThroughSlotsFnArr: [],
    updatePassThroughSlotsFnArr: (fnArr: (() => VNode[])[]) => {
      this.context = {
        ...this.context,
        getPassThroughSlotsFnArr: fnArr,
      };
      this.passThroughSlots = fnArr.flatMap((fn) => fn());
    },
  };
  @State() passThroughSlots: VNode[] = [];
  /**
   * @private */
  @Prop() wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /**
   * @private */
  @Prop() setDynamicRenderDeps: (children: unknown[], getPassThroughSlots?: () => VNode[]) => void = noop;
}
