import { CascaderDataNode, SearchConfig } from '../types';

export const defaultFilter: SearchConfig['filter'] = (search, options) =>
  options.some((opt) => String(opt.label).toLowerCase().includes(search.toLowerCase()));

export function getDefaultLabel(search: string, path: CascaderDataNode[]): string {
  if (path.some((item) => typeof item.label === 'function')) {
    console.warn('PLEASE IMPLEMENT CUSTOM RENDER FUNC');
    return '';
  }
  return path.map((n) => n.label).join(' / ') || '';
}
